document.addEventListener("alpine:init",()=>{Alpine.data("RockCommerce",()=>({init(){RockCommerce.addComponent(this);RockCommerce.config=JSON.parse(this.$rcattr("data-config")||"{}");document.dispatchEvent(new CustomEvent("RockCommerce:ready"))},}))});document.addEventListener("alpine:init",()=>{Alpine.magic("rcpid",(el)=>{const c=RockCommerce.getComponent(el);return c.$rcattr("rc-pid")});Alpine.magic("rcattr",(el)=>{const c=RockCommerce.getComponent(el);return(attr)=>c.$root.getAttribute(attr)});Alpine.magic("rctype",(el)=>{const c=RockCommerce.getComponent(el);return c.$el.getAttribute("x-data")})})